def rectangles(strings):
    """
    Count the number of rectangles in an ASCII diagram.

    A rectangle is defined by four '+' characters at its corners. The horizontal
    edges between corner '+' characters must be made up only of '-' or '+'
    characters. The vertical edges between corner '+' characters must be made
    up only of '|' or '+' characters.
    """
    if not strings:
        return 0

    rows = len(strings)
    cols = len(strings[0])

    grid = strings  # list of strings, constant-length lines guaranteed

    # Precompute positions of '+' per row
    plus_positions_in_row = []
    for r in range(rows):
        pluses = [c for c, ch in enumerate(grid[r]) if ch == '+']
        plus_positions_in_row.append(pluses)

    def horizontal_ok(r, c1, c2):
        # assumes grid[r][c1] == grid[r][c2] == '+'
        for c in range(c1 + 1, c2):
            ch = grid[r][c]
            if ch not in ('-', '+'):
                return False
        return True

    def vertical_ok(c, r1, r2):
        # assumes grid[r1][c] == grid[r2][c] == '+'
        for r in range(r1 + 1, r2):
            ch = grid[r][c]
            if ch not in ('|', '+'):
                return False
        return True

    count = 0
    # For each pair of pluses on the same row (possible top edge)
    for r1 in range(rows):
        pluses = plus_positions_in_row[r1]
        n = len(pluses)
        if n < 2:
            continue
        for i in range(n):
            for j in range(i + 1, n):
                c1 = pluses[i]
                c2 = pluses[j]
                # Check top horizontal edge valid
                if not horizontal_ok(r1, c1, c2):
                    continue
                # Look for matching bottom edges on lower rows
                for r2 in range(r1 + 1, rows):
                    # Need '+' at both (r2,c1) and (r2,c2)
                    if grid[r2][c1] != '+' or grid[r2][c2] != '+':
                        continue
                    # Check bottom horizontal edge
                    if not horizontal_ok(r2, c1, c2):
                        continue
                    # Check vertical edges on both sides
                    if vertical_ok(c1, r1, r2) and vertical_ok(c2, r1, r2):
                        count += 1
    return count
